INSERT INTO `characters` VALUES (1,21,'Jinx (Powder)','jinx-powder','League of Legends / Arcane','A manic and impulsive criminal from Zaun, Jinx lives to wreak havoc without care for the consequences, armed with an arsenal of deadly custom weapons.','Fishbones Rocket Launcher, Pow-Pow Minigun, Flame Chompers, Chemtech Enhancement',NULL,NULL,1,'active','2026-09-24 07:12:43','2026-09-24 07:12:43'),(2,22,'Miles Morales','miles-morales','Spider-Man Multiverse','Brooklyn teenager bitten by a genetically altered spider who assumes the mantle of Spider-Man across interdimensional realities.','Wall-crawling, Spider-Sense, Bio-Electric Venom Strike, Active Camouflage',NULL,NULL,1,'active','2026-09-24 07:12:43','2026-09-24 07:12:43'),(3,21,'Geralt of Rivia','geralt-of-rivia','The Witcher Universe','A magically enhanced Witcher of the School of the Wolf who wanders the Continent slaying mythical beasts for coin while entangled in the destiny of Ciri.','Silver & Steel Swordsmanship, Witcher Signs (Aard, Igni, Quen, Axii, Yrden), Alchemy & Mutagens',NULL,NULL,1,'active','2026-09-24 07:12:43','2026-09-24 07:12:43'),(4,20,'Lucy Kushinada','lucy-kushinada','Cyberpunk: Edgerunners','A quiet and enigmatic netrunner who escaped an Arasaka research lab, dreaming of leaving Night City to build a peaceful life on the Moon.','Advanced Deep-Dive Netrunning, Monowire Combat, ICE Breaking, Rapid Cyberware Hacking',NULL,NULL,1,'active','2026-09-24 07:12:43','2026-09-24 07:12:43'),(5,28,'Commander Kaito Test','commander-kaito-test','Cyber Chronicles','Elite cyber security agent guarding the nexus core.',NULL,NULL,NULL,0,'active','2026-09-24 12:40:10','2026-09-24 12:40:10'),(6,30,'Major Motoko Test','major-motoko-test','Ghost in the Shell','Cyborg squad commander of Section 9.','Thermo-optic camouflage, advanced cyberbrain hacking',NULL,NULL,1,'active','2026-09-24 12:51:16','2026-09-24 12:51:16'),(7,30,'Batou Modified','batou-modified','Ghost in the Shell SAC','Updated biography notes.',NULL,NU