INSERT INTO `chatbot_knowledge` VALUES (1,NULL,'What is Fan Hub Plus?','Fan Hub Plus is an interactive digital universe for fandom culture, bringing together anime, gaming, sci-fi, k-pop, fantasy, superheroes, comics, and esports fans into a unified platform. You can explore rich content lore, character databases, fan creations, upcoming events, and release schedules all in one place.','[\"fan hub plus\",\"about\",\"overview\",\"platform\",\"what is\",\"intro\"]',1,42,'2026-09-24 12:34:27','2026-09-24 12:34:27'),(2,NULL,'What fandom categories are available?','Fan Hub Plus currently supports 8 major fandom categories: Anime, Gaming, Sci-Fi, K-Pop, Fantasy, Superheroes, Comics, and Esports. You can explore curated content, lore, multimedia, and active fan communities for each fandom from the main navigation menu.','[\"fandoms\",\"categories\",\"genres\",\"anime\",\"gaming\",\"sci-fi\",\"k-pop\",\"fantasy\",\"superheroes\",\"comics\",\"esports\"]',1,38,'2026-09-24 12:34:27','2026-09-24 12:34:27'),(3,NULL,'How do I create an account or sign in?','You can create a free account by clicking the \'Register\' button in the top navigation bar. Enter your name, email, and password. If you already have an account, click \'Login\' to access your personalized bookmarks, ratings, and submission history.','[\"register\",\"sign up\",\"login\",\"account\",\"auth\",\"password\",\"join\"]',1,25,'2026-09-24 12:34:27','2026-09-24 12:34:27'),(4,NULL,'How do I bookmark content and add personal notes?','When viewing any content page (movies, anime, games, lore articles), click the \'Bookmark\' button. You can select a status (Reading, Watching, Completed, Plan to Watch) and add custom private notes for your personal watchlist.','[\"bookmark\",\"save\",\"favorites\",\"watchlist\",\"notes\",\"status\",\"reading\",\"watching\"]',1,19,'2026-09-24 12:34:27','2026-09-24 12:34:27'),(5,NULL,'How do I submit fan creations or multimedia?','Registered members can share fan art, wallpapers, audio, and videos! Navigate to the \'Multimedia\' center and click \'Submit Fan Work\'. Choose your media type, upload your file or provide an external URL, and pick the associated fandom category.','[\"submit\",\"fan work\",\"multimedia\",\"upload\",\"fan art\",\"video\",\"audio\",\"wallpaper\",\"creations\"]',1,31,'2026-09-24 12:34:27','2026-09-24 12:34:27'),(6,NULL,'How do I find upcoming events and conventions?','Visit the \'Events Radar\' page from the top navigation. You can filter events by fandom category, event type (Convention, Tournament, Premiere, Concert), date range, and view locations on an interactive discovery map with direct ticket links.','[\"events\",\"conventions\",\"tournaments\",\"tickets\",\"map\",\"dates\",\"upcoming\",\"schedule\"]',1,27,'2026-09-24 12:34:27','2026-09-24 12:34:27'),(7,NULL,'How do I track upcoming releases and countdowns?','Head over to the \'Release Radar\' section. You will see real-time countdown timers for anticipated video games, anime seasons, films, and albums, with quick filters by platform and status.','[\"releases\",\"countdown\",\"premiere\",\"launch\",\"release date\",\"calendar\",\"upcoming games\"]',1,34,'2026-09-24 12:34:27','2026-09-24 12:34:27'),(8,NULL,'How do I change display preferences and theme?','Click your user avatar in the top right corner and navigate to \'Preferences\'. There you can toggle Dark/Light mode, change your primary fandom focus, and adjust email/notification preferences.','[\"theme\",\"dark mode\",\"light mode\",\"preferences\",\"settings\",\"fandom preference\",\"appearance\"]',1,15,'2026-09-24 12:34:27','2026-09-24 12:34:27'),(9,NULL,'How can I rate content and leave reviews?','On any content detail page, scroll down to the Community Feedback section. Select a 1-to-5 star rating and write your review to share your insights with fellow fans.','[\"rating\",\"stars\",\"review\",\"feedback\",\"score\",\"rate\"]',1,14,'2026-09-24 12:34:27','2026-09-24 12:34:27'),(10,NULL,'Where can I find character profiles and faction lore?','Explore individual Fandom Content Hubs (such as Anime or Gaming) and click on the \'Characters\' tab. You\'ll find comprehensive character profiles, affiliations, voice actors, first appearances, and backstories.','[\"characters\",\"lore\",\"profiles\",\"heroes\",\"villains\",\"factions\",\"backstory\"]',1,22,'2026-09-24 12:34:27','2026-09-24 12:34:27'),(11,NULL,'How do I contact administrators or report an issue?','If you encounter any inappropriate content or experience a technical issue, please email our moderation team at admin@fanhubplus.com or use the moderation flag option on fan content posts.','[\"contact\",\"support\",\"report\",\"moderation\",\"help\",\"admin\",\"issue\",\"bug\"]',1,11,'2026-09-24 12:34:27','2026-09-24 12:34:27'),(12,NULL,'What is the moderation policy for fan art?','All submitted fan works are reviewed by our moderation team within 24 hours.','[\"moderation\",\"policy\",\"rules\"]',1,0,'2026-09-24 12:35:54','2026-09-24 12:35:54'),(13,NULL,'Is there a dark mode toggle?','Yes, in your profile preferences.','[\"theme\",\"dark mode\"]',1,0,'2026-09-24 12:35:55','2026-09-24 12:35:55'),(14,NULL,'Temporary FAQ entry to be deleted','Temporary answer.','[\"temp\"]',1,0,'2026-09-24 12:35:55','2026-09-24 12:35:55'),(15,29,'How do I earn fan badges on Fan Hub Plus?','You can earn fan badges by participating in discussions and submitting verified fan works.','[\"badges\",\"rewards\",\"achievements\",\"fan points\"]',1,0,'2026-09-24 12:38:04','2026-09-24 12:38:04'),(16,NULL,'What is the updated moderation policy for fan art?','All submitted fan works are reviewed by our moderation team within 12 hours.','[\"moderation\",\"policy\",\"rules\",\"guidelines\"]',1,0,'2026-09-24 12:38:04','2026-09-24 12:38:04'),(17,NULL,'Is there a dark mode toggle option?','Yes, in your profile preferences.','[\"theme\",\"dark mode\"]',0,0,'2026-09-24 12:38:05','2026-09-24 12:38:05'),(19,29,'How do I earn fan badges on Fan Hub Plus?','You can earn fan badges by participating in discussions and submitting verified fan works.','[\"badges\",\"rewards\",\"achievements\",\"fan points\"]',1,0,'2026-09-24 12:38:35','2026-09-24 12:38:35'),(20,NULL,'What is the updated moderation policy for fan art?','All submitted fan works are reviewed by our moderation team within 12 hours.','[\"moderation\",\"policy\",\"rules\",\"guidelines\"]',1,0,'2026-09-24 12:38:35','2026-09-24 12:38:35'),(21,NULL,'Is there a dark mode toggle option?','Yes, in your profile preferences.','[\"theme\",\"dark mode\"]',0,0,'2026-09-24 12:38:35','2026-09-24 12:38:35'),(23,29,'How do I earn fan badges on Fan Hub Plus?','You can earn fan badges by participating in discussions and submitting verified fan works.','[\"badges\",\"rewards\",\"achievements\",\"fan points\"]',1,0,'2026-09-24 12:39:31','2026-09-24 12:39:31'),(24,NULL,'What is the updated moderation policy for fan art?','All submitted fan works are reviewed by our moderation team within 12 hours.','[\"moderation\",\"policy\",\"rules\",\"guidelines\"]',1,0,'2026-09-24 12:39:31','2026-09-24 12:39:31'),(25,NULL,'Is there a dark mode toggle option?','Yes, in your profile preferences.','[\"theme\",\"dark mode\"]',0,0,'2026-09-24 12:39:31','2026-09-24 12:39:31'),(27,29,'How do I earn fan badges on Fan Hub Plus?','You can earn fan badges by participating in discussions and submitting verified fan works.','[\"badges\",\"rewards\",\"achievements\",\"fan points\"]',1,0,'2026-09-24 12:40:09','2026-09-24 12:40:09'),(28,NULL,'What is the updated moderation policy for fan art?','All submitted fan works are reviewed by our moderation team within 12 hours.','[\"moderation\",\"policy\",\"rules\",\"guidelines\"]',1,0,'2026-09-24 12:40:09','2026-09-24 12:40:09'),(29,NULL,'Is there a dark mode toggle option?','Yes, in your profile preferences.','[\"theme\",\"dark mode\"]',0,0,'2026-09-24 12:40:09','2026-09-24 12:40:09'),(31,29,'How do I earn fan badges on Fan Hub Plus?','You can earn fan badges by participa