INSERT INTO `contents` VALUES (16,21,41,'Arcane: League of Legends Worldbuilding Deep Dive','arcane-league-of-legends-worldbuilding','article','Champion sisters Vi and Jinx find themselves on opposing sides of a burgeoning conflict over conflicting technologies and twisted convictions in Piltover and Zaun.','An in-depth retrospective exploring the animation craft of Fortiche, musical score design, and narrative transformation of Runeterra lore.',NULL,NULL,'2021-11-06',11,980,1,'published','2026-09-24 12:34:27',NULL,'2026-09-24 07:12:43','2026-09-24 13:25:18'),(17,20,41,'Cyberpunk: Edgerunners — The Neon Tragedy of Night City','cyberpunk-edgerunners-neon-tragedy','article','Studio Trigger and CD PROJEKT RED deliver an intense, emotional adrenaline thrill through Mike Pondsmith’s dystopian universe.','Analysis of David Martinez’s tragic arc and the visual language of cyberware psychosis.',NULL,NULL,'2022-09-13',0,945,1,'published','2026-09-24 12:34:27',NULL,'2026-09-24 07:12:43','2026-09-24 12:34:27'),(18,22,41,'Spider-Man: Across the Spider-Verse — Visual Revolution','spider-man-across-the-spider-verse-visual-revolution','article','Miles Morales catapults across dimension-shifting realities, blending comic print halftone dots, watercolor, and punk zine aesthetics.','A complete review of the artistic techniques powering Earth-65, Mumbattan, and Nueva York.',NULL,NULL,'2023-06-02',0,992,1,'published','2026-09-24 12:34:27',NULL,'2026-09-24 07:12:43','2026-09-24 12:34:27'),(19,26,41,'Solo Leveling: Evolution of Modern Webtoon Action','solo-leveling-evolution-of-modern-webtoon-action','article','How Chugong and DUBU revolutionized vertical scroll paneling, shadow monarch summoning, and international manhwa popularity.','From the catastrophic double dungeon raid to Sung Jinwoo standing atop the monarch hierarchy.',NULL,NULL,'2024-01-06',0,870,1,'published','2026-09-24 12:34:27',NULL,'2026-09-24 07:12:43','2026-09-24 12:34:27'),(20,21,44,'Elden Ring: Shadow of the Erdtree L