--
-- Table structure for table `events`
--

DROP TABLE IF EXISTS `events`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `events` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `category_id` bigint(20) unsigned DEFAULT NULL,
  `title` varchar(500) NOT NULL,
  `slug` varchar(500) NOT NULL,
  `description` text DEFAULT NULL,
  `cover_image` varchar(500) DEFAULT NULL,
  `event_type` enum('convention','cosplay_meetup','screening','livestream','release_event','concert','other') NOT NULL DEFAULT 'other',
  `starts_at` datetime NOT NULL,
  `ends_at` datetime DEFAULT NULL,
  `venue_name` varchar(500) DEFAULT NULL,
  `address` varchar(500) DEFAULT NULL,
  `city` varchar(255) DEFAULT NULL,
  `country` varchar(255) DEFAULT NULL,
  `latitude` decimal(10,8) DEFAULT NULL,
  `longitude` decimal(11,8) DEFAULT NULL,
  `ticket_url` varchar(1000) DEFAULT NULL,
  `is_featured` tinyint(1) NOT NULL DEFAULT 0,
  `is_online` tinyint(1) NOT NULL DEFAULT 0,
  `status` enum('upcoming','ongoing','completed','cancelled') NOT NULL DEFAULT 'upcoming',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `events_slug_unique` (`slug`),
  KEY `events_category_id_index` (`category_id`),
  KEY `events_event_type_index` (`event_type`),
  KEY `events_status_index` (`status`),
  KEY `events_starts_at_index` (`starts_at`),
  KEY `events_is_featured_index` (`is_featured`),
  CONSTRAINT `events_category_id_foreign` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=60 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `events`
--

LOCK TABLES `events` WRITE;
/*!40000 ALTER TABLE `events` DISABLE KEYS */;
INSERT INTO `events` VALUES (1,25,'Comic-Con International: San Diego 2026','comic-con-international-2026','The premier pop culture and comic book convention in the world, featuring Hall H studio reveals, legendary artist alleys, and cosmic fandom celebrations.',NULL,'convention','2026-07-23 09:00:00','2026-07-26 18:00:00','San Diego Convention Center','111 W Harbor Dr, San Diego, CA 92101','San Diego','United States',32.70720000,-117.16330000,'https://www.comic-con.org/cci',1,0,'upcoming','2026-09-24 07:12:44','2026-09-24 08:14:58'),(2,21,'Tokyo Game Show 2026','tokyo-game-show-2026','One of the world’s major video game expos with global game world premieres, esports championships, and next-generation interactive hardware demos.',NULL,'convention','2026-09-24 10:00:00','2026-09-27 18:00:00','Makuhari Messe','2 Chome-1 Nakase, Mihama Ward, Chiba, 261-0023','Chiba','Japan',35.64830000,140.03470000,'https://tgs.nikkeibp.co.jp/tgs',1,0,'upcoming','2026-09-24 07:12:44','2026-09-24 08:14:58'),(3,27,'World Cosplay Summit 2026','world-cosplay-summit-2026','The international championship celebrating costume craftsmanship, dramatic theatrical performances, and global cosplay brotherhood.',NULL,'cosplay_meetup','2026-08-01 11:00:00','2026-08-03 20:00:00','Oasis 21 & Aichi Arts Center','1-11-1 Higashisakura, Higashi Ward, Nagoya, Aichi 461-0005','Nagoya','Japan',35.17090000,136.90840000,'https://worldcosplaysummit.jp',1,0,'upcoming','2026-09-24 07:12:44','2026-09-24 08:14:58'),(4,20,'MCM London Comic Con & Anime Festival','mcm-london-comic-con-2026','The UK\'s largest modern pop culture event encompassing gaming, anime, comics, and live celebrity stages.',NULL,'convention','2026-10-23 10:00:00','2026-10-25 18:00:00','ExCeL London','Royal Victoria Dock, 1 Western Gateway, London E16 1XL','London','United Kingdom',51.50850000,0.02980000,'https://www.mcmcomiccon.com/london',1,0,'upcoming','2026-09-24 08:14:58','2026-09-24 08:14:58'),(5,20,'Anime Expo 2026: Los Angeles','anime-expo-los-angeles-2026','The biggest North American celebration of Japanese animation and pop culture, bringing fans and industry together for an unforgettable 4-day experience.',NULL,'convention','2026-07-02 09:00:00','2026-07-05 18:00:00','Los Angeles Convention Center','1201 S Figueroa St, Los Angeles, CA 90015','Los Angeles','United States',34.04070000,-118.26940000,'https://www.anime-expo.org',0,0,'upcoming','2026-09-24 08:14:58','2026-09-24 08:14:58'),(6,21,'Gamescom 2026 Cologne','gamescom-2026-cologne','The world’s largest event for computer and video games and Europe’s leading business platform for the games industry.',NULL,'convention','2026-08-19 09:00:00','2026-08-23 20:00:00','Koelnmesse','Messepl. 1, 50679 Köln, Germany','Cologne','Germany',50.94630000,6.98060000,'https://www.gamescom.global',0,0,'upcoming','2026-09-24 08:14:58','2026-09-24 08:14:58'),(7,24,'K-Culture Seoul Fandom Expo','k-culture-seoul-fandom-expo','A three-night mega festival celebrating K-Pop live stages, fan lightstick synchronization, and agency showcase auditions.',NULL,'concert','2026-11-12 18:00:00','2026-11-14 22:00:00','KSPO Dome (Olympic Gymnastics Arena)','424 Olympic-ro, Songpa-gu, Seoul','Seoul','South Korea',37.51900000,127.12750000,'https://ticket.interpark.com',1,0,'upcoming','2026-09-24 08:14:58','2026-09-24 08:14:58'),(8,20,'Tokyo Retro Anime Midnight Marathon','tokyo-retro-anime-marathon','A vintage 35mm film projection marathon celebrating classic cyberpunk anime from the golden 1980s and 1990s eras.',NULL,'screening','2025-12-15 22:00:00','2025-12-16 06:00:00','Shinjuku Piccadilly Cinema','3 Chome-15-15 Shinjuku, Tokyo 160-0022','Tokyo','Japan',35.69380000,139.70340000,'https://www.smt-cinema.com',0,0,'completed','2026-09-24 08:15:43','2026-09-24 08:15:43'),(9,21,'Tokyo Game Show Test 2026','tokyo-game-show-test-2026','International gaming convention in Chiba, Japan.',NULL,'convention','2026-09-26 18:25:13','2026-09-29 18:25:13','Makuhari Messe Test',NULL,'Chiba','Jap