INSERT INTO `releases` VALUES (1,21,'Grand Theft Auto VI','grand-theft-auto-vi','game','The next monumental evolution in open-world storytelling set across the sun-soaked state of Leonida and neon-drenched streets of Vice City.',NULL,'2026-11-15','PlayStation 5, Xbox Series X/S','Rockstar Games','https://www.rockstargames.com/VI','upcoming','[\"Pre-Order\",\"Collector\'s Edition\"]',1,'2026-09-24 07:12:43','2026-09-24 08:14:58'),(2,22,'Avengers: Secret Wars','avengers-secret-wars','movie','The epic culmination of the Marvel Cinematic Universe Multiverse Saga bringing legacy heroes face to face with cosmic cataclysms on Battleworld.',NULL,'2027-05-07','Theatrical / IMAX','Marvel Studios','https://www.marvel.com/movies','upcoming','[\"IMAX Special\",\"Multiverse Epic\"]',1,'2026-09-24 07:12:43','2026-09-24 08:14:58'),(3,20,'Chainsaw Man: The Movie — Reze Arc','chainsaw-man-reze-arc-movie','anime','Studio MAPPA’s cinematic continuation of Tatsuki Fujimoto’s manga, introducing the deadly and explosive Bomb Devil Reze.',NULL,'2026-10-25','Theatrical Worldwide','MAPPA / Toho Animation','https://chainsawman.dog','upcoming','[\"Limited Edition\",\"Theatrical\"]',1,'2026-09-24 07:12:44','2026-09-24 08:14:58'),(4,21,'Final Fantasy VII: Reunion & Zenith','final-fantasy-vii-reunion-zenith','game','The climactic final entry of Square Enix’s legendary remake trilogy, following Cloud and his companions to the Northern Crater.',NULL,'2027-03-20','PlayStation 5','Square Enix','https://ffvii.square-enix-games.com','upcoming','[\"Pre-Order\",\"Steelbook Edition\",\"Collectible\"]',1,'2026-09-24 08:14:58','2026-09-24 08:14:58'),(5,26,'Solo Leveling: Complete Box Set Edition','solo-leveling-box-set','manga','Deluxe hardcover slipcase edition including all 14 volumes, exclusive art prints, and high-gloss foil covers.',NULL,'2026-12-05','Print / Hardcover Slipcase','Yen Press / D&C Media','https://yenpress.com','upcoming','[\"Limited Edition\",\"Collectible\",\"Pre-Order\"]',0,'2026-09-24 08:14:58','2026-09-24 08:14:58'),(6,27,'Arcane: Jinx Fishbones 1:1 Prop Replica','arcane-jinx-fishbones-replica','merchandise','Officially licensed life-size 1:1 scale replica of Jinx\'s signature rocket launcher, featuring illuminated LED jaw and authentic Zaunite weathering.',NULL,'2026-11-01','Collectible Prop Art','Riot Games Merchandise / PureArts','https://merch.riotgames.com','upcoming','[\"Limited Edition\",\"Collectible\",\"Pre-Order\"]',1,'2026-09-24 08:14:58','2026-09-24 08:14:58'),(7,24,'BTS 2026 World Tour Commemorative Vinyl','bts-world-tour-vinyl','merchandise','Deluxe 4xLP gatefold vinyl edition pressed on luminescent purple vinyl, including 120-page full-color photobook and holographic photocards.',NULL,'2026-11-20','Vinyl / Audiophile Edition','Big Hit Music / HYBE','https://weverse.io','upcoming','[\"Limited Edition\",\"Collectible\",\"Pre-Order\"]',0,'2026-09-24 08:14:58','2026-09-24 08:14:58'),(8,21,'Test Grand Theft Auto VI Release','test-gta-vi-release','game','Anticipated open world game release.',NULL,'2026-09-26','PS5, Xbox','Rockstar Games','https://www.rockstargames.com','upcoming','[\"Pre-Order\",\"Collector\'s Edition\"]',1,'2026-09-24 08:18:31','2026-09-24 12:17:49'),(9,20,'Test Chainsaw Man Movie Release','test-chainsaw-man-movie-release','anime','Anime movie worldwide premiere.',NULL,'2026-09-27','Theatrical','MAPPA','https://chainsawman.dog','upcoming','[\"Limited Edition\"]',1,'2026-09-24 08:18:31','2026-09-24 12:17:49'),(10,21,'Final Fantasy XVI PC Edition Test','final-fantasy-xvi-pc-edition-test','game','Epic dark fantasy action RPG ported to PC platform.',NULL,'2026-11-24','PC / Steam','Square Enix','https://square-enix-games.com','upcoming','[\"Pre-Order\",\"Limited Edition\",\"4K HDR\"]',1,'2026-09-24 08:19:10','2026-09-24 08:19:10'),(11,21,'Updated Release Title','updated-release-title','game',NULL,NULL,'2026-10-14','Nintendo Switch OLED',NULL,NULL,'upcoming','[\"Pre-Order\",\"Collectible\"]',0,'2026-09-24 08:19:10','2026-09